Below is an example `pytest`‐style test module covering

- the happy paths
- a variety of edge cases
- and some error cases

Save this as e.g. `test_zip_dicts.py` (and adjust the import line to point at wherever your `zip_dicts` lives).

```python
import pytest

# Adjust this import to wherever zip_dicts is defined.
# For example, if you have zip_dicts in zip_utils.py do:
# from zip_utils import zip_dicts
from your_module import zip_dicts


def test_no_dicts_returns_empty_dict():
    # When called with no arguments, should return an empty dict
    assert zip_dicts() == {}


def test_single_dict_happy_path():
    d = {'a': 1, 'b': 2}
    # zip_dicts should wrap each value in a single‐element list
    assert zip_dicts(d) == {'a': [1], 'b': [2]}


def test_two_dicts_same_keys():
    d1 = {'x': 10, 'y': 20}
    d2 = {'x': 30, 'y': 40}
    expected = {
        'x': [10, 30],
        'y': [20, 40],
    }
    assert zip_dicts(d1, d2) == expected


def test_two_dicts_disjoint_keys():
    d1 = {'a': 1}
    d2 = {'b': 2}
    # 'a' only in d1 => second slot is None; 'b' only in d2 => first slot is None
    assert zip_dicts(d1, d2) == {
        'a': [1, None],
        'b': [None, 2],
    }


def test_empty_dict_among_others():
    # An empty dict yields only None slots
    d1 = {}
    d2 = {'foo': 'bar'}
    assert zip_dicts(d1, d2) == {'foo': [None, 'bar']}


def test_multiple_dicts_partial_overlap_and_none_values():
    d1 = {'a': None, 'b': 2}
    d2 = {'b': 3, 'c': None}
    d3 = {'a': 4, 'c': 5}

    # Keys are union of all three: {'a','b','c'}
    # For each key, collect [d1.get, d2.get, d3.get]
    expected = {
        'a': [None, None, 4],    # a missing in d2 => None
        'b': [2, 3, None],       # b missing in d3 => None
        'c': [None, None, 5],    # c missing in d1 & value None in d2
    }
    assert zip_dicts(d1, d2, d3) == expected


def test_various_key_types():
    # keys can be any hashable type
    d1 = {1: 'one', (2, 3): 'tuple23'}
    d2 = {1: 'uno', (4, 5): 'tuple45'}
    result = zip_dicts(d1, d2)
    assert result == {
        1: ['one', 'uno'],
        (2, 3): ['tuple23', None],
        (4, 5): [None, 'tuple45'],
    }


def test_returned_lists_are_independent_of_inputs():
    d1 = {'a': 1}
    d2 = {'a': 2}
    result = zip_dicts(d1, d2)

    # Mutating the returned lists must not change the originals
    result['a'][0] = 999
    assert d1['a'] == 1

    result['a'][1] = 888
    assert d2['a'] == 2


@pytest.mark.parametrize("bad_input", [
    None,
    123,
    "not a dict",
    [("a", 1)],
])
def test_non_dict_raises(bad_input):
    # At least one non‐mapping should blow up
    with pytest.raises(Exception):
        zip_dicts({'a': 1}, bad_input)


def test_no_iterable_keys_raises_on_union():
    # If you pass e.g. an int as a second positional
    # union(*dicts) tries to iterate it and fails
    with pytest.raises(TypeError):
        zip_dicts({'a': 1}, 5)
```

Explanation of what is being covered:

1. `test_no_dicts_returns_empty_dict`: calling with no arguments returns `{}`.
2. `test_single_dict_happy_path`: wrapping a single dict works as expected.
3. `test_two_dicts_same_keys` & `test_two_dicts_disjoint_keys`: both overlapping and non‐overlapping.
4. `test_empty_dict_among_others`: one of the dicts is empty.
5. `test_multiple_dicts_partial_overlap_and_none_values`: complex case with `None` both as missing key and actual value.
6. `test_various_key_types`: integer and tuple keys.
7. `test_returned_lists_are_independent_of_inputs`: ensure immutability of inputs.
8. Parameterized `test_non_dict_raises`: passing common non‐mapping types causes an exception.
9. `test_no_iterable_keys_raises_on_union`: specifically shows the `TypeError` from `set().union(...)` when a non‐iterable is passed.

Feel free to adjust exception types (`TypeError` vs. `AttributeError` vs. generic `Exception`) according to the exact behaviour in your environment.
